 const parts=local.split("/").filter(Boolean);
 if(!parts.length)return {route:"home",slug:""};
 if(parts[0]==="explore")return {route:"explore",slug:""};
 if(parts[0]==="my-works"&&parts[1]==="edit"&&parts[2])return {route:"write",slug:parts[2]};
 if(parts[0]==="my-works"&&parts[1]==="new")return {route:"write",slug:"",kind:parts[2]||"post"};
 if(parts[0]==="my-works")return {route:"work",slug:""};
 if(parts[0]==="write")return {route:"write",slug:""};
 if(parts[0]==="settings")return {route:"settings",slug:""};
 if(parts[0]==="reviews")return {route:"reviews",slug:""};
 if(parts[0]==="signin")return {route:"signin",slug:""};
 if(parts[0]==="signup")return {route:"signup",slug:""};
 if(parts[0]==="forgot-password")return {route:"forgot",slug:""};
 if(parts[0]==="reset-password")return {route:"reset",slug:""};
 if(parts[0]==="onboarding")return {route:"onboarding",slug:""};
 if(parts[0]==="profile"&&sharedUsername)return {route:"public",slug:sharedUsername};
 if(parts[0]==="profile")return {route:"profile",slug:""};
 if(parts[0]==="u"&&parts[1])return {route:"public",slug:parts[1]};
 if(["posts","books","services"].includes(parts[0])&&parts[1])return {route:"item",slug:parts[1],kind:parts[0]==="posts"?"post":parts[0]==="books"?"book":"service"};
