function markdownHref(url){const value=(url||"").trim();if(!value)return "";if(/^(https?:|mailto:)/i.test(value)||/^\/(?!\/)/.test(value)||/^#[\w-]+$/.test(value))return value;return ""}
function MarkdownInline({text=""}){const pattern=/(`[^`]+?`|\*\*[^*]+?\*\*|__[^_]+?__|~~[^~]+?~~|(?<!\*)\*[^*\n]+?\*(?!\*)|(?<!_)_[^_\n]+?_(?!_)|\[[^\]]+\]\([^)]+\))/g;const parts=String(text).split(pattern);return <>{parts.map((part,i)=>{if(!part)return null;if(part.startsWith("`")&&part.endsWith("`"))return <code key={i}>{part.slice(1,-1)}</code>;if(part.startsWith("**")&&part.endsWith("**"))return <strong key={i}>{part.slice(2,-2)}</strong>;if(part.startsWith("__")&&part.endsWith("__"))return <strong key={i}>{part.slice(2,-2)}</strong>;if(part.startsWith("~~")&&part.endsWith("~~"))return <del key={i}>{part.slice(2,-2)}</del>;if(part.startsWith("*")&&part.endsWith("*"))return <em key={i}>{part.slice(1,-1)}</em>;if(part.startsWith("_")&&part.endsWith("_"))return <em key={i}>{part.slice(1,-1)}</em>;if(part.startsWith("[")&&part.includes("](")){const match=part.match(/^\[([^\]]+)\]\(([^)]+)\)$/);const href=markdownHref(match?.[2]);return href?<a key={i} href={href} target={/^https?:/i.test(href)?"_blank":undefined} rel={/^https?:/i.test(href)?"noopener noreferrer":undefined}><MarkdownInline text={match[1]}/></a>:<>{part}</>;}return part;})}</>}
function Markdown({source="",className=""}){const lines=String(source||"").replace(/\r\n?/g,"\n").split("\n");const blocks=[];let i=0;while(i<lines.length){const line=lines[i];if(!line.trim()){i++;continue;}if(/^\s*```/.test(line)){const lang=line.trim().slice(3).trim();const code=[];i++;while(i<lines.length&&!/^\s*```/.test(lines[i]))code.push(lines[i++]);if(i<lines.length)i++;blocks.push(<pre key={"code"+i} data-language={lang||undefined}><code>{code.join("\n")}</code></pre>);continue;}if(/^\s*(---+|\*\*\*+|___+)\s*$/.test(line)){blocks.push(<hr key={"hr"+i}/>);i++;continue;}const heading=line.match(/^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/);if(heading){const Tag="h"+heading[1].length;blocks.push(<Tag key={"h"+i}><MarkdownInline text={heading[2]}/></Tag>);i++;continue;}if(/^\s*>/.test(line)){const quote=[];while(i<lines.length&&/^\s*>/.test(lines[i]))quote.push(lines[i++].replace(/^\s*>\s?/,""));blocks.push(<blockquote key={"q"+i}><Markdown source={quote.join("\n")}/></blockquote>);continue;}if(/^\s*([-*+]\s+|\d+[.)]\s+)/.test(line)){const ordered=/^\s*\d+[.)]\s+/.test(line);const list=[];while(i<lines.length&&/^\s*([-*+]\s+|\d+[.)]\s+)/.test(lines[i])){list.push(lines[i].replace(/^\s*(?:[-*+]\s+|\d+[.)]\s+)/,""));i++;}const Tag=ordered?"ol":"ul";blocks.push(<Tag key={"list"+i}>{list.map((item,n)=><li key={n}><MarkdownInline text={item}/></li>)}</Tag>);continue;}const para=[line.trim()];i++;while(i<lines.length&&lines[i].trim()&&!/^\s{0,3}#{1,6}\s+/.test(lines[i])&&!/^\s*>/.test(lines[i])&&!/^\s*([-*+]\s+|\d+[.)]\s+)/.test(lines[i])&&!/^\s*```/.test(lines[i])&&!/^\s*(---+|\*\*\*+|___+)\s*$/.test(lines[i]))para.push(lines[i++].trim());blocks.push(<p key={"p"+i}>{para.map((part,n)=><React.Fragment key={n}>{n>0&&<br/>}<MarkdownInline text={part}/></React.Fragment>)}</p>);}return <div className={"ab-markdown "+className}>{blocks}</div>}
